import { promises as fs } from 'node:fs';
import path from 'node:path';
import PizZip from 'pizzip';
import { zipSync } from 'fflate';

export const ALLOCATED_DOCUMENT_TEMPLATES = [
  { id: 'contrato-base', label: 'Contrato Base', file: 'contrato-base.docx' },
  { id: 'termo-compromisso', label: 'Termo de compromisso', file: 'termo-compromisso.docx' },
  { id: 'vinculo-tecnico-profissional', label: 'Vinculo Tecnico Profissional', file: 'vinculo-tecnico-profissional.docx' }
];

const EMBEDDED_TEMPLATE_BASE64 = {
  'contrato-base.docx': '',
  'termo-compromisso.docx': '',
  'vinculo-tecnico-profissional.docx': ''
};

const MONTHS = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

function clean(value, fallback = '') {
  const text = String(value ?? '').trim();
  return text || fallback;
}

function escapeXml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function formatFilename(value) {
  return clean(value, 'documento')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80) || 'documento';
}

function parseDate(value) {
  const text = clean(value);
  const match = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!match) return null;
  return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
}

function formatLongDate(value = new Date(), lowercaseMonth = false) {
  const date = value instanceof Date ? value : parseDate(value);
  if (!date || Number.isNaN(date.getTime())) return '';
  const month = MONTHS[date.getMonth()] || '';
  return `${String(date.getDate()).padStart(2, '0')} de ${lowercaseMonth ? month.toLowerCase() : month} de ${date.getFullYear()}`;
}

function formatShortDate(value) {
  const date = parseDate(value);
  if (!date || Number.isNaN(date.getTime())) return '';
  return `${String(date.getDate()).padStart(2, '0')}/${String(date.getMonth() + 1).padStart(2, '0')}/${date.getFullYear()}`;
}

function formatCurrency(value) {
  return Number(value || 0).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  });
}

const UNITS = ['', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove'];
const TEENS = ['dez', 'onze', 'doze', 'treze', 'quatorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
const TENS = ['', '', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
const HUNDREDS = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos', 'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];

function integerToWords(number) {
  const value = Math.trunc(Number(number || 0));
  if (value === 0) return 'zero';
  if (value === 100) return 'cem';
  if (value < 10) return UNITS[value];
  if (value < 20) return TEENS[value - 10];
  if (value < 100) {
    const unit = value % 10;
    return `${TENS[Math.trunc(value / 10)]}${unit ? ` e ${UNITS[unit]}` : ''}`;
  }
  if (value < 1000) {
    const rest = value % 100;
    return `${HUNDREDS[Math.trunc(value / 100)]}${rest ? ` e ${integerToWords(rest)}` : ''}`;
  }
  if (value < 1000000) {
    const thousands = Math.trunc(value / 1000);
    const rest = value % 1000;
    const prefix = thousands === 1 ? 'mil' : `${integerToWords(thousands)} mil`;
    return `${prefix}${rest ? ` e ${integerToWords(rest)}` : ''}`;
  }
  return String(value);
}

function currencyWords(value) {
  const amount = Math.round(Number(value || 0) * 100);
  const reais = Math.trunc(amount / 100);
  const cents = amount % 100;
  const realText = `${integerToWords(reais)} ${reais === 1 ? 'real' : 'reais'}`;
  if (!cents) return realText;
  return `${realText} e ${integerToWords(cents)} ${cents === 1 ? 'centavo' : 'centavos'}`;
}

function titleCaseName(value) {
  return clean(value)
    .toLocaleLowerCase('pt-BR')
    .replace(/\b(\p{L})/gu, (letter) => letter.toLocaleUpperCase('pt-BR'));
}

function addressLine(allocated) {
  const address = clean(allocated.contactAddress || allocated.companyAddress);
  const city = clean(allocated.contactCity || allocated.companyCity);
  const state = clean(allocated.contactState || allocated.companyState);
  const zip = clean(allocated.contactZip || allocated.companyZip);
  return [
    address,
    city && state ? `${city} - ${state}` : city || state,
    zip ? `CEP: ${zip}` : ''
  ].filter(Boolean).join(', ');
}

function prepareAllocatedDocumentData(allocated, clientName) {
  const today = new Date();
  const consultant = titleCaseName(allocated.consultant);
  const companyName = clean(allocated.companyName, consultant);
  const companyCnpj = clean(allocated.companyCnpj, 'não informado');
  const companyAddress = clean(allocated.companyAddress || allocated.contactAddress, 'não informado');
  const companyZip = clean(allocated.companyZip || allocated.contactZip, 'não informado');
  const companyCity = clean(allocated.companyCity || allocated.contactCity, 'não informada');
  const companyState = clean(allocated.companyState || allocated.contactState, '');
  const client = clean(clientName, 'cliente');
  const hourlyRate = Number(allocated.hourlyRate || 0);

  const contractorBlock = `${companyName}, sociedade empresária inscrita no CNPJ/MF sob o n.º ${companyCnpj} com endereço na ${companyAddress}, CEP ${companyZip}, Cidade de ${companyCity}${companyState ? `, ${companyState}` : ''}, neste ato representada na forma de seu Estatuto Social, doravante denominada CONTRATADA.`;
  const priceClause = `3.1. Pelos serviços prestados pela CONTRATADA, a CONTRATANTE pagará os valores referentes aos serviços prestados, medidos mensalmente, com um valor definido de ${formatCurrency(hourlyRate)} (${currencyWords(hourlyRate)} por hora), que serão pagos todo dia 15 (quinze) do mês subsequente.`;
  const commitmentIntro = `Através deste instrumento eu, ${consultant}, residente a ${addressLine(allocated) || 'endereço não informado'}, portador(a) da Carteira de Identidade RG nº ${clean(allocated.rg, 'não informado')}, inscrito(a) no CPF/MF sob nº ${clean(allocated.cpf, 'não informado')}, abaixo assinado, entendo que no exercício das minhas atividades ${client.toLocaleUpperCase('pt-BR')} em virtude da prestação de serviços avençada com a empresa ALCATEIA TALENTOS HUMANOS E TECNOLOGIA LTDA, poderei receber, ter acesso, desenvolver ou vir a ter conhecimento de informações confidenciais pertencentes ao cliente ou a seus clientes, incluindo, mas não se limitando a toda e qualquer informação técnica, operacional, comercial, jurídica, know-how, invenções, processos, fórmulas e designs, patenteáveis ou não, planos de negócios, métodos contábeis, técnicas e experiências acumuladas, documentos, contratos, papéis, estudos, pareceres, pesquisas e informações de qualquer natureza, tangíveis ou intangíveis, armazenadas ou não (“Informações Confidenciais”).`;

  return {
    code: clean(allocated.code, 'sem-codigo'),
    clientName: client,
    consultant,
    contractor_block: contractorBlock,
    price_clause: priceClause,
    commitment_intro: commitmentIntro,
    contact_address_line: addressLine(allocated) || 'não informado',
    phone: clean(allocated.phone, 'não informado'),
    consultantEmail: clean(allocated.consultantEmail, 'não informado'),
    today_long: formatLongDate(today),
    today_long_lower: formatLongDate(today, true),
    startDateShort: formatShortDate(allocated.startDate) || formatShortDate(today.toISOString().slice(0, 10)),
    rg: clean(allocated.rg, 'não informado'),
    cpf: clean(allocated.cpf, 'não informado'),
    contractType: clean(allocated.contractType, 'PJ'),
    companyCnpj,
    hourlyRate: formatCurrency(hourlyRate),
    hourlyRateWords: currencyWords(hourlyRate)
  };
}

function replacePlaceholders(xml, data) {
  return Object.entries(data).reduce((current, [key, value]) => {
    const token = `{${key}}`;
    return current.split(token).join(escapeXml(value));
  }, xml);
}

async function loadTemplateBuffer(templatePath) {
  try {
    return await fs.readFile(templatePath);
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    const embedded = EMBEDDED_TEMPLATE_BASE64[path.basename(templatePath)];
    if (!embedded) throw error;
    return Buffer.from(embedded, 'base64');
  }
}

async function renderAllocatedDocx(templatePath, data) {
  const template = await loadTemplateBuffer(templatePath);
  const zip = new PizZip(template);
  Object.keys(zip.files)
    .filter((name) => /^word\/.*\.xml$/.test(name))
    .forEach((name) => {
      const file = zip.file(name);
      if (!file) return;
      zip.file(name, replacePlaceholders(file.asText(), data));
    });
  return zip.generate({ type: 'nodebuffer', compression: 'DEFLATE' });
}

export async function renderAllocatedDocuments(allocateds, clients, templateIds, templateDirectory) {
  const selectedTemplates = ALLOCATED_DOCUMENT_TEMPLATES.filter((template) => templateIds.includes(template.id));
  const clientById = new Map(clients.map((client) => [client.id, client.customerName]));
  const documents = [];

  for (const allocated of allocateds) {
    const data = prepareAllocatedDocumentData(allocated, clientById.get(allocated.clientId));
    for (const template of selectedTemplates) {
      const content = await renderAllocatedDocx(path.join(templateDirectory, template.file), data);
      const filename = `${formatFilename(allocated.consultant)}-${formatFilename(allocated.code)}-${formatFilename(template.label)}.docx`;
      documents.push({ filename, content, templateId: template.id, allocatedId: allocated.id });
    }
  }

  return documents;
}

export function buildAllocatedDocumentsZip(documents) {
  return Buffer.from(zipSync(Object.fromEntries(
    documents.map((document) => [document.filename, new Uint8Array(document.content)])
  ), { level: 6 }));
}
